// BAD: Improper use of Java API leading to vulnerabilities
// Scenario 1: SQL Injection via Statement and string concatenation
// Scenario 2: Path Traversal via File with unvalidated user input
// Scenario 3: XSS via echoing unescaped request parameter
import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class InsecureServlet extends HttpServlet {
    private Connection getConnection() throws Exception {
        // Demo only: hardcoded credentials; also vulnerable if logged/committed to VCS
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/appdb", "appuser", "apppass");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String userId = req.getParameter("userId"); // trusted without validation
        String filename = req.getParameter("file"); // trusted without validation

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) {

            // VULNERABLE: SQL injection via string concatenation
            String sql = "SELECT username, email FROM users WHERE id = " + userId;
            ResultSet rs = stmt.executeQuery(sql);

            PrintWriter out = resp.getWriter();
            resp.setContentType("text/html");

            if (rs.next()) {
                String username = rs.getString("username");
                String email = rs.getString("email");

                // VULNERABLE: XSS by directly reflecting parameter back to the client
                out.println("<h1>User " + userId + "</h1>");
                out.println("<p>Name: " + username + "</p>");
                out.println("<p>Email: " + email + "</p>");
            }

            // VULNERABLE: Path traversal by using unvalidated user input to build file path
            File file = new File("/var/app/uploads/" + filename);
            try (BufferedReader br = new BufferedReader(new FileReader(file))) {
                out.println("<pre>");
                String line;
                while ((line = br.readLine()) != null) {
                    out.println(line);
                }
                out.println("</pre>");
            }
        } catch (Exception e) {
            // Overly verbose error exposure can leak stack traces and secrets
            resp.sendError(500, "Error: " + e.getMessage());
        }
    }
}
***
/* GOOD: Properly using Java APIs to prevent common vulnerabilities
   - Use PreparedStatement with parameter binding to prevent SQL injection
   - Validate and constrain path inputs; resolve and verify canonical path within allowed directory
   - HTML-escape untrusted output to prevent XSS
   - Avoid leaking internal errors to clients
*/
import java.io.*;
import java.nio.file.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class SecureServlet extends HttpServlet {
    private static final Path UPLOADS_DIR = Paths.get("/var/app/uploads").toAbsolutePath().normalize();

    private Connection getConnection() throws Exception {
        // In production, use a connection pool (e.g., HikariCP) and externalized credentials
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/appdb", "appuser", "apppass");
    }

    private static String htmlEscape(String s) {
        if (s == null) return "";
        // Minimal HTML escaping to mitigate XSS
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#x27;");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        // Validate and parse userId as numeric to prevent injection and logic errors
        String userIdParam = req.getParameter("userId");
        Integer userId = null;
        try {
            userId = Integer.valueOf(userIdParam);
        } catch (Exception e) {
            resp.sendError(400, "Invalid userId");
            return;
        }

        String filenameParam = req.getParameter("file");
        // Basic filename whitelist: only allow simple names without separators
        if (filenameParam != null && (filenameParam.contains("..") || filenameParam.contains("/") || filenameParam.contains("\\") || filenameParam.isBlank())) {
            resp.sendError(400, "Invalid file name");
            return;
        }

        resp.setContentType("text/html; charset=UTF-8");
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement("SELECT username, email FROM users WHERE id = ?")) {

            // SAFE: Bind parameter instead of concatenating (fixes previously vulnerable code)
            ps.setInt(1, userId);
            ResultSet rs = ps.executeQuery();

            PrintWriter out = resp.getWriter();

            if (rs.next()) {
                String username = rs.getString("username");
                String email = rs.getString("email");

                // SAFE: Escape untrusted output to prevent XSS
                out.println("<h1>User " + htmlEscape(String.valueOf(userId)) + "</h1>");
                out.println("<p>Name: " + htmlEscape(username) + "</p>");
                out.println("<p>Email: " + htmlEscape(email) + "</p>");
            } else {
                out.println("<p>User not found.</p>");
            }

            // SAFE: Resolve and verify canonical path to prevent path traversal
            if (filenameParam != null) {
                Path requested = UPLOADS_DIR.resolve(filenameParam).normalize();
                if (!requested.startsWith(UPLOADS_DIR)) {
                    resp.sendError(403, "Access denied");
                    return;
                }
                File file = requested.toFile();
                if (!file.exists() || !file.isFile()) {
                    resp.sendError(404, "File not found");
                    return;
                }
                try (BufferedReader br = new BufferedReader(new FileReader(file))) {
                    out.println("<pre>");
                    String line;
                    while ((line = br.readLine()) != null) {
                        // Optionally escape to avoid HTML injection from file contents
                        out.println(htmlEscape(line));
                    }
                    out.println("</pre>");
                }
            }
        } catch (SQLException e) {
            // Log internally with a logger; return generic error to client
            resp.sendError(500, "Internal server error");
        } catch (Exception e) {
            resp.sendError(500, "Internal server error");
        }
    }
}

