// BAD: Demonstrates improper Java API usage leading to vulnerabilities
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.Base64;

public class InsecureLoginServlet extends HttpServlet {
    // NOTE: This example is intentionally vulnerable and for demonstration only.
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // 1) SQL Injection: Using string concatenation is vulnerable
        String sql = "SELECT id, username FROM users WHERE username = '" + username +
                     "' AND password = '" + password + "'"; // vulnerable

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "root", "root");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            if (rs.next()) {
                // 2) Insecure cookie: not setting HttpOnly/Secure/SameSite flags
                Cookie session = new Cookie("session", rs.getString("id"));
                resp.addCookie(session);

                // 3) Sensitive data exposure: echoing user-controlled data directly
                resp.getWriter().println("Welcome " + username); // vulnerable to XSS if username contains HTML
            } else {
                resp.getWriter().println("Invalid credentials");
            }
        } catch (SQLException e) {
            // 4) Information leakage: returning raw error details to client
            resp.getWriter().println("DB error: " + e.getMessage()); // vulnerable
        }

        // 5) Insecure deserialization: blindly decoding and using user input
        String serialized = req.getParameter("prefsB64");
        if (serialized != null) {
            try {
                byte[] bytes = Base64.getDecoder().decode(serialized);
                ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(bytes));
                Object prefs = ois.readObject(); // vulnerable: could trigger gadget chain
                resp.getWriter().println("Loaded prefs: " + prefs);
            } catch (Exception ex) {
                resp.getWriter().println("Prefs error: " + ex.getMessage());
            }
        }
    }
}

