// GOOD: Secure usage of Java APIs to mitigate vulnerabilities
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class SecureLoginServlet extends HttpServlet {

    // Use a connection pool in real apps (e.g., HikariCP)
    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection("jdbc:mysql://localhost/app?useSSL=true", "appuser", "strong-password");
    }

    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        resp.setContentType("text/plain; charset=UTF-8");

        // Validate and normalize input
        String username = safeParam(req.getParameter("username"), 150);
        String password = safeParam(req.getParameter("password"), 150);

        // Use parameterized query to prevent SQL injection
        String sql = "SELECT id, username, password_hash FROM users WHERE username = ?";

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, username);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next() && verifyPassword(password, rs.getString("password_hash"))) {
                    // Generate a strong session token (use server session or JWT with care)
                    String token = newSessionToken();

                    // Set cookie flags: HttpOnly, Secure, and SameSite
                    Cookie session = new Cookie("session", token);
                    session.setHttpOnly(true);
                    session.setSecure(true);
                    session.setPath("/");
                    // SameSite via response header if not available on Cookie API in your servlet container
                    resp.addHeader("Set-Cookie", String.format("session=%s; Path=/; HttpOnly; Secure; SameSite=Strict", token));
                    resp.addCookie(session);

                    // Avoid reflecting raw user input; encode if needed
                    resp.getWriter().println("Welcome!");
                } else {
                    // Generic error message to prevent info leakage
                    resp.getWriter().println("Invalid credentials");
                }
            }
        } catch (SQLException e) {
            // Log server-side; return generic message client-side
            log("Database error", e);
            resp.getWriter().println("An error occurred");
        }

        // Safe handling of user-provided structured data: parse vetted formats only
        String prefsJson = req.getParameter("prefsJson");
        if (prefsJson != null) {
            try {
                Map<String, Object> prefs = parseLimitedJson(prefsJson); // whitelist-based parser
                resp.getWriter().println("Prefs saved");
            } catch (Exception ex) {
                log("Invalid prefs JSON", ex);
                resp.getWriter().println("Invalid preferences");
            }
        }
    }

    // Helper: limit length, strip controls
    private String safeParam(String s, int max) {
        if (s == null) return "";
        String trimmed = s.trim();
        if (trimmed.length() > max) trimmed = trimmed.substring(0, max);
        return trimmed.replaceAll("\\p{Cntrl}", "");
    }

    // Helper: strong random session token
    private String newSessionToken() {
        byte[] bytes = new byte[32];
        ThreadLocalRandom.current().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    // Helper: verify password using a secure hash (e.g., BCrypt, Argon2). Placeholder here.
    private boolean verifyPassword(String password, String hash) {
        // Use a real password hashing library; never compare raw passwords
        return fakeBCryptCheck(password, hash);
    }

    // Placeholder for a proper JSON parser with strict schema validation
    private Map<String, Object> parseLimitedJson(String json) throws Exception {
        // In production, use a safe library (e.g., Jackson) with a DTO and @JsonIgnoreProperties(ignoreUnknown = true)
        Map<String, Object> out = new HashMap<>();
        if (json.length() > 5000) throw new IllegalArgumentException("Too large");
        if (json.contains("\0")) throw new IllegalArgumentException("Invalid");
        // Minimal demo parsing
        out.put("theme", "light");
        return out;
    }

    // Placeholder fake BCrypt check
    private boolean fakeBCryptCheck(String password, String hash) {
        // Replace with BCrypt.checkpw(password, hash)
        return Objects.equals(hash, "hash-of-" + password);
    }
}

